    "level2_formula": "remember + to Vo = không quên bổn phận/nhiệm vụ cần thực hiện.",
    "level3_steps": "Lời dặn học sinh trước khi rời phòng thí nghiệm phải nhớ khóa van gas và tắt điện (nhiệm vụ cần làm) -> Dùng 'to turn off'. Đáp án B."
